window.__posterData({"id": "hanan", "name": "Hanan Mughrabi", "folder": "Week 45 - AI-rave_poster-Hanan", "v": "2", "scripts": ["https://cdn.jsdelivr.net/npm/p5@2.3.4/lib/p5.js", "https://cdn.jsdelivr.net/npm/p5.js-compatibility@0.2.0/src/shapes.js", "https://cdn.jsdelivr.net/npm/p5.js-compatibility@0.2.0/src/data.js", "https://cdn.jsdelivr.net/npm/p5.js-compatibility@0.2.0/src/preload.js", "https://cdn.jsdelivr.net/npm/p5.sound@0.4.1/dist/p5.sound.min.js"], "links": [], "css": "html, body {\n  margin: 0;\n  padding: 0;\n}\ncanvas {\n  display: block;\n}\n", "code": "// Hanan mughrabi\nlet firstImage, secondImage;\n\n// Rave-läget är stängt\nlet rave = false;\n\n// Lista för fyrkanter\nlet squares = [];\n\n// NEW FEATURE: Neon Beat Pulse\nlet beatPulse = 0;\nlet beatSpeed = 0.12;\n\n// färger som ska vara med\nconst COLORS = [\n  '#FF00AA',\n  '#00FFFF',\n  '#7000FF',\n  '#D7FF00',\n  '#FF0055'\n];\n\n// Färre fyrkanter så bilen syns bättre, denna ändrig gjorde det mer organiserat och höll fokus\nconst NUM_SQUARES = 55;\nconst TRAIL_LENGTH = 14;\n\n// Laddar bilderna \nfunction preload() {\n  firstImage = loadImage('images-1.jpg');\n  secondImage = loadImage('img-trip.png');\n}\n\n// Skapar canvas och dess storlek och centerar texten\nfunction setup() {\n  createCanvas(600, 800);\n  textAlign(CENTER, CENTER);\n//Ger kvadraterna slumpmässiga egenskaper, till exempel position, storlek, hastighet, rotation och färg.\n  for (let i = 0; i < NUM_SQUARES; i++) {\n    squares.push({\n      x: random(width),\n      y: random(height),\n      size: random(10, 45),\n      speedX: random(-10, 10),\n      speedY: random(-10, 10),\n      angle: random(TWO_PI),\n      spin: random(-0.1, 0.1),\n      color: random(COLORS),\n      trail: []\n    });\n  }\n}\n\n// Rita hela postern\nfunction draw() {\n  background('#050010');\n\n  drawImage();\n\n  // Visa fyrkanter endast i rave-läge\n  if (rave) {\n    drawSquares();\n  }\n\n  drawText();\n  drawFrame();\n\n  // NEW FEATURE: Pulsating neon frame - AI har lagt till\n  drawNeonBeat();\n}\n\n// Visa rätt bild\nfunction drawImage() {\n  let img = rave ? secondImage : firstImage;\n\n  // Anpassa bilden till canvasen\n  let imageScale = max(\n    width / img.width,\n    height / img.height\n  );\n\n  // bild storlek genom skala\n  let imageWidth = img.width * imageScale;\n  let imageHeight = img.height * imageScale;\n\n  imageMode(CENTER);\n\n  image(\n    img,\n    width / 2,\n    height / 2,\n    imageWidth,\n    imageHeight\n  );\n\n  // kantlinje\n  imageMode(CORNER);\n\n  // Mörkt filter för neonfärgerna\n  noStroke();\n  fill(5, 0, 20, 65);\n  rect(0, 0, width, height);\n}\n\n// Rita kvadrater med mjuka neonspår - Trail delen la AI till\nfunction drawSquares() {\n  squares.forEach(s => {\n\n    // Spara tidigare positioner\n    s.trail.push({\n      x: s.x,\n      y: s.y,\n      angle: s.angle,\n      color: s.color\n    });\n\n    // Begränsa spårets längd\n    if (s.trail.length > TRAIL_LENGTH) {\n      s.trail.shift();\n    }\n\n    // Rita neonspåren\n    for (let i = 0; i < s.trail.length; i++) {\n      let t = s.trail[i];\n\n      push();\n\n      translate(t.x, t.y);\n      rotate(t.angle);\n      rectMode(CENTER);\n\n      let progress = (i + 1) / s.trail.length;\n\n      // Genomskinliga spår\n      let trailOpacity = 3 + progress * 40;\n\n      let trailSize =\n        s.size * (0.2 + progress * 0.6);\n\n      let trailColor = color(t.color);\n      trailColor.setAlpha(trailOpacity);\n\n      noStroke();\n      fill(trailColor);\n\n      // Mjuk neonglöd\n      drawingContext.shadowBlur = 20;\n      drawingContext.shadowColor = t.color;\n\n      rect(0, 0, trailSize, trailSize);\n\n      pop();\n    }\n\n    // Rita huvudfyrkanten\n    push();\n\n    translate(s.x, s.y);\n    rotate(s.angle);\n    rectMode(CENTER);\n\n    let squareColor = color(s.color);\n    squareColor.setAlpha(65);\n\n    fill(squareColor);\n    stroke(s.color);\n    strokeWeight(1.5);\n\n    // Neonglöd\n    drawingContext.shadowBlur = 25;\n    drawingContext.shadowColor = s.color;\n\n    rect(0, 0, s.size, s.size);\n\n    pop();\n\n    // Mjuk rörelse\n    s.x += s.speedX * 1.2;\n    s.y += s.speedY * 1.2;\n\n    // Rotation\n    s.angle += s.spin * 2;\n\n    // Studsa mot kanterna\n    if (s.x < 0 || s.x > width) {\n      s.speedX *= -1;\n    }\n\n    if (s.y < 0 || s.y > height) {\n      s.speedY *= -1;\n    }\n  });\n}\n\n// Bestämelser för texten på sidan\nfunction drawText() {\n  textAlign(CENTER, CENTER);\n  textStyle(BOLD);\n  textFont('Arial');\n  noStroke();\n\n  // Text längst upp\n  fill('#00FFFF');\n  textSize(12);\n  text('TOKYO', 80, 35);\n\n  fill('#fff700');\n  text('SÖDERTÖRN', 510, 35);\n\n  fill(255);\n  textSize(13);\n  text('STREET DRIVING', 300, 80);\n\n  // Glitch-effekt efter klick\n  let shake = rave ? random(-20, 20) : 0;\n\n  textFont('Impact');\n  textStyle(ITALIC);\n\n  // Rosa TOKYO\n  drawingContext.shadowBlur = 30;\n  drawingContext.shadowColor = '#FF00AA';\n\n  fill('#FF00AA');\n  textSize(112);\n  text('TOKYO', 300 + shake, 145);\n\n  // Blå RAVE\n  drawingContext.shadowColor = '#00FFFF';\n\n  fill('#00FFFF');\n  textSize(85);\n  text('RAVE', 300 - shake, 240);\n\n  drawingContext.shadowBlur = 0;\n\n  textFont('Arial');\n  textStyle(BOLD);\n\n  fill('#D7FF00');\n  textSize(16);\n  text('DRIVE // FUN // REPEAT', 300, 300);\n\n  // Information\n  fill('#D7FF00');\n  textSize(13);\n  text('NO EAT. NO SLEEP.', 300, 600);\n\n  fill('#FF00AA');\n  textSize(28);\n  text('TOKYO NIGHT RAVE', 300, 650);\n\n  fill('#00FFFF');\n  textSize(20);\n  text('23:59 // TOKYO // 2026', 300, 720);\n\n  // Text som ändras vid klick\n  textSize(18);\n\n  if (rave) {\n    fill('#D7FF00');\n    text('RAVE MODE ACTIVATED', 300, 750);\n  } else {\n    fill('#FF00AA');\n    text('CLICK TO START THE RAVE', 300, 750);\n  }\n\n  // Mitt namn\n  fill(255);\n  textSize(18);\n  text('HANAN MUGHRABI', 300, 778);\n}\n\n// Rita neonramen\nfunction drawFrame() {\n  push();\n\n  noFill();\n\n  if (rave) {\n    stroke('#FF00AA');\n    drawingContext.shadowColor = '#FF00AA';\n  } else {\n    stroke('#00FFFF');\n    drawingContext.shadowColor = '#00FFFF';\n  }\n// Ger skuggeffekt för kantlinje\n  drawingContext.shadowBlur = 18;\n  strokeWeight(2);\n\n  rect(12, 12, 576, 776);\n\n  pop();\n}\n\n// ======================================\n// NEW FEATURE: NEON BEAT PULSE\n// ======================================\n\n// Neonramen pulserar och byter färg\n// när rave-läget är aktiverat\nfunction drawNeonBeat() {\n\n  // Ingen animation när rave är av\n  if (!rave) return;\n\n  // Mjuk pulserande rörelse\n  beatPulse =\n    (sin(frameCount * beatSpeed) + 1) / 2;\n\n  // Glöden blir större och mindre\n  let glowSize = map(\n    beatPulse,\n    0, 1,\n    10, 45\n  );\n\n  // Ramens tjocklek ändras till smal och tjock\n  let frameWeight = map(\n    beatPulse,\n    0, 1,\n    2, 7\n  );\n\n  // Byt neonfärg automatiskt\n  let colorIndex =\n    floor(frameCount / 15) % COLORS.length;\n\n  let beatColor = COLORS[colorIndex];\n\n  push();\n\n  noFill();\n  stroke(beatColor);\n  strokeWeight(frameWeight);\n\n  // Stark neonglöd\n  drawingContext.shadowBlur = glowSize;\n  drawingContext.shadowColor = beatColor;\n\n  // Rita pulserande neonram\n  rect(\n    12,\n    12,\n    width - 24,\n    height - 24\n  );\n\n  pop();\n}\n\n\n// Klicka och see....\nfunction mousePressed() {\n  rave = !rave;\n\n  squares.forEach(s => {\n    s.speedX = random(-30, 30);\n    s.speedY = random(-30, 30);\n    s.color = random(COLORS);\n\n    // Återställ neonspåren\n    s.trail = [];\n  });\n\n  // Starta pulsen från början\n  beatPulse = 0;\n}\n\n// Jag använde mig av Chat-gpt och skcikade exakta prompts enligt uppgiften.\n\n//Första steget gjorde att strukturen förbättrades och organiserades, tog bort om det fanns repitioner. Den klargjorde även några namn exempelvis istället för s att det står square. ingen funktion ändrades och allt bevarades. \n\n// Andra steget ville jag att kvadraterna skulle ha mjukare rörelse och att de ska ha ett lysande spår efter sig. AI valde själv att använda flera transparanta kvadrater för att skapa trail-effekten. Detta tyckte jag om men första utkastet blev för mycket kvadrater och med trail-effekten så försvann bakgrunsbildens fokus. Därefter bad jag den att minska antalet kvadrater ett antal gånger. AI valde först 25 fyrkanter, men jag tyckte att det blev för tomt. Jag bad om fler kvadrater då ändrade den i två omgångar 45 och till sist 55 fyrkanter. Det resulterade i att effekten passade bra till temat och gjorde det mer levande. Under denna omgång fick jag också felmeddelanden om alpha och rect() så var tvungen att säga det till AI.\n\n// Tredje steget - Efter att jag skicka prompten så föreslog AI att ändra neonramen till en pulserande ram som ändrar färg, tjocklek och ljusstyrka. Uppskattar det faktikt, tycker att det gav mer energi och behöll fokuset. \n\n// För mig lärde jag mig och trail-length, viste inte exakt vad det var innan men var verkligen en effekt jag ville ha med nu i efterhand, känner att det gjorde skillnad och bidrog till livligheten.  Något som ändrades fast jag inte skrev til AI var att kvadraterna ska röra sig långsammare,så det var intressant men trots det tyckte jag det var en bra ändring. Något som jag inte förstod exakt var sin(frameCount * beatSpeed) men förstår nu att den gör pulserande rörelse där kanlinjen blir tjock och tunn med glödeffekt med \"beat\" rhytm. Tycker att postern som helhet blev bättre än tidigare då den inte är lika överväldigande.\n\n", "assets": {"images-1.jpg": {"mime": "image/webp", "b64": ""}, "img-trip.png": {"mime": "image/webp", "b64": ""}}});
